mapper.sql:
rta_match_in_season AS ( SELECT m.replay_id AS rid, m.played_at AS date_add, m.winner_wizard_id, m.battle_type FROM public.rta_match m WHERE
m.season_id = #{seasonId}
FALSE
)

pool_500 AS ( SELECT * FROM summoner_rank_detail ORDER BY max_score DESC, wizard_id ASC LIMIT 500 ), pool_scored AS ( SELECT p.wizard_id, p.max_score, p.wizard_name, p.country, p.channel_uid, p.score, p.rating_id, p.last_match_at, ROW_NUMBER() OVER (ORDER BY p.max_score DESC, p.wizard_id ASC) AS rank_position FROM pool_500 p ), pool_filtered AS ( SELECT * FROM pool_scored WHERE 1 = 1
AND ( CASE WHEN TRIM(COALESCE(country::text, '')) = '' THEN '—' ELSE TRIM(country::text) END ) = #{countryFilter}
)

sql.if:
AND EXISTS (
	SELECT 1
	FROM public.rta_match_participant pp
	WHERE pp.replay_id = m.replay_id
	  AND pp.rating_id IN (
		SELECT rg.rating_id
		FROM public.rta_rating_grade rg
		WHERE rg.tier_key = #{tierKey}
	  )
)
